def _parse_pre_version(letter, number):
    if letter:
        # We consider the "rc" form of a pre-release to be long-form for the
        # "c" form, thus we normalize "rc" to "c" so we can properly compare
        # them as equal. The "alpha" and "beta" forms are normalized down to
        # their short forms, and a missing number means "0".
        if number is None:
            number = 0

        letter = letter.lower()
        if letter == "rc":
            letter = "c"
        elif letter == "alpha":
            letter = "a"
        elif letter == "beta":
            letter = "b"

        return (letter, int(number))

